import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编译与运行","link":"/guide/programming_guide/compilation_and_execution/compilation_and_execution"},{"text":"算子编译","link":"/guide/programming_guide/compilation_and_execution/operator_compilation/bisheng_compiler"},{"text":"RTC运行时编译","link":"/guide/programming_guide/compilation_and_execution/operator_compilation/rtc_runtime_compilation"}]},"headers":[],"relativePath":"guide/programming_guide/compilation_and_execution/operator_compilation/rtc_runtime_compilation.md","filePath":"guide/programming_guide/compilation_and_execution/operator_compilation/rtc_runtime_compilation.md","lastUpdated":1787050286000}'),l={name:"guide/programming_guide/compilation_and_execution/operator_compilation/rtc_runtime_compilation.md"};function t(e,s,o,r,i,d){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>RTC<span id="ZH-CN_TOPIC_0000002462620725"></span></h1><p>RTC是Ascend C运行时编译库，通过<a href="../../../../api/Utils-API/RTC/RTC.html">aclrtc</a>接口，在程序运行时，将中间代码动态编译成目标机器码，提升程序运行性能。</p><p>运行时编译库提供以下核心接口：</p><ul><li>aclrtcCreateProg：根据输入参数（字符串形式表达的Ascend C源代码等）创建aclrtcProg程序实例。</li><li>aclrtcAddNameExpr（可选）：注册需要导出的核函数（Kernel）名表达式，支持模板参数（如&quot;核函数（Kernel）::add_custom&lt;float&gt;&quot;），非模板核函数（Kernel）可跳过。</li><li>aclrtcCompileProg：编译给定的程序，支持用户自定义编译选项，比如指定<a href="../../language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本号</a>：--npu-arch=dav-2201。支持的编译选项可以参考<a href="https://www.hiascend.com/document/redirect/CannCommunityBiSheng">《毕昇编译器用户指南》</a>。</li><li>aclrtcGetBinDataSize：获取编译后的Device侧二进制数据的大小。</li><li>aclrtcGetBinData：获取编译后的Device侧二进制数据。</li><li>aclrtcGetLoweredName（可选）：获取核函数（Kernel）编译后的mangled name，用于后续通过aclrtBinaryGetFunction查找核函数（Kernel）句柄，非模板核函数（Kernel）可跳过。</li><li>aclrtcDestroyProg：在编译和执行过程结束后，销毁给定的程序。</li></ul><p>编译完成后需要调用如下接口完成（仅列出核心接口）核函数（Kernel）加载与执行。完整流程和详细接口说明请参考<a href="https://hiascend.com/document/redirect/CannCommunityRuntimeApi">《Runtime运行时API》</a>中的“核函数（Kernel）加载与执行”章节。</p><ol><li>调用aclInit、aclrtSetDevice等接口初始化运行环境并指定Device。</li><li>通过aclrtBinaryLoadFromData接口解析由aclrtcGetBinData接口获取的算子二进制数据。加载时可通过ACL_RT_BINARY_LOAD_OPT_MAGIC指定二进制类型，如ACL_RT_BINARY_MAGIC_ELF_AICORE。</li><li>调用aclrtBinaryGetFunction接口获取核函数（Kernel）句柄。</li><li>调用aclrtLaunchKernelWithArgsArray接口，在已创建的Stream上按参数数组方式启动对应算子的计算任务。无参数核函数（Kernel）可传入空参数数组；有参数核函数（Kernel）需保证参数数组元素按核函数（Kernel）入参顺序排列，且每个元素指向Host侧的参数值。</li><li>调用aclrtSynchronizeStream、aclrtBinaryUnLoad、aclrtDestroyStream、aclrtResetDevice、aclFinalize等接口完成同步和资源释放。</li></ol><p>如下样例演示了如何使用aclrtc接口编译并运行一个核函数（Kernel），该核函数（Kernel）中调用了printf进行打印。完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/02_features/05_aclrtc/rtc_hello_world/README.md">LINK</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;cstdio&gt;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;vector&gt;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;acl/acl.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;acl/acl_rt_compile.h&quot;</span><span class="w"> </span><span class="c1">// 使用aclrtc接口需要包含的头文件</span>

<span class="cp">#ifndef ACL_RTC_NPU_ARCH</span>
<span class="cp">#define ACL_RTC_NPU_ARCH &quot;dav-2201&quot;</span>
<span class="cp">#endif</span>

<span class="cp">#define ASCENDC_CHECK(expr) do {               \\</span>
<span class="cp">    aclError ret = (expr);                     \\</span>
<span class="cp">    if (ret != ACL_SUCCESS) {                  \\</span>
<span class="cp">        fprintf(stderr,                        \\</span>
<span class="cp">            &quot;Ascend Error: %s:%d code=%d %s\\n&quot;,\\</span>
<span class="cp">            __FILE__, __LINE__,                \\</span>
<span class="cp">            ret, aclGetRecentErrMsg());        \\</span>
<span class="cp">        return ret;                            \\</span>
<span class="cp">    }                                          \\</span>
<span class="cp">} while(0)</span>

<span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="o">*</span><span class="n">src</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="sa">R</span><span class="s">&quot;</span><span class="dl">&quot;&quot;&quot;(</span>
<span class="s">#include &quot;utils/debug/asc_printf.h&quot;</span>
<span class="s">extern &quot;C&quot; __global__ __vector__ void hello_world()</span>
<span class="s">{</span>
<span class="s">    printf(&quot;Hello World!!!\\n&quot;);</span>
<span class="s">}</span>
<span class="dl">)&quot;&quot;&quot;</span><span class="s">&quot;</span><span class="p">;</span>

<span class="kt">int</span><span class="w"> </span><span class="nf">main</span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="n">argc</span><span class="p">,</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="o">*</span><span class="n">argv</span><span class="p">[])</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">aclrtcProg</span><span class="w"> </span><span class="n">prog</span><span class="p">;</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtcCreateProg</span><span class="p">(</span><span class="o">&amp;</span><span class="n">prog</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="s">&quot;hello_world.asc&quot;</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">,</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">));</span>

<span class="w">    </span><span class="c1">// aclrtc流程，传入毕昇编译器的编译选项，调用aclrtcCompileProg进行编译</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="o">*</span><span class="n">options</span><span class="p">[]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="s">&quot;--npu-arch=&quot;</span><span class="w"> </span><span class="n">ACL_RTC_NPU_ARCH</span><span class="p">,</span>
<span class="w">    </span><span class="p">};</span>
<span class="w">    </span><span class="kt">int</span><span class="w"> </span><span class="n">numOptions</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">options</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">options</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span>
<span class="w">    </span><span class="n">aclError</span><span class="w"> </span><span class="n">ret</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">aclrtcCompileProg</span><span class="p">(</span><span class="n">prog</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">options</span><span class="p">);</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ret</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="n">ACL_SUCCESS</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">size_t</span><span class="w"> </span><span class="n">size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="w">        </span><span class="p">(</span><span class="kt">void</span><span class="p">)</span><span class="n">aclrtcGetCompileLogSize</span><span class="p">(</span><span class="n">prog</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">size</span><span class="p">);</span>
<span class="w">        </span><span class="kt">char</span><span class="w"> </span><span class="n">log</span><span class="p">[</span><span class="n">size</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="mi">0</span><span class="p">};</span>
<span class="w">        </span><span class="p">(</span><span class="kt">void</span><span class="p">)</span><span class="n">aclrtcGetCompileLog</span><span class="p">(</span><span class="n">prog</span><span class="p">,</span><span class="w"> </span><span class="n">log</span><span class="p">);</span>
<span class="w">        </span><span class="n">printf</span><span class="p">(</span><span class="s">&quot;Compile Error Log : %s&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">log</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="c1">// aclrtc流程，获取Device侧二进制内容和大小</span>
<span class="w">    </span><span class="kt">size_t</span><span class="w"> </span><span class="n">binDataSizeRet</span><span class="p">;</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtcGetBinDataSize</span><span class="p">(</span><span class="n">prog</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">binDataSizeRet</span><span class="p">));</span>
<span class="w">    </span><span class="n">std</span><span class="o">::</span><span class="n">vector</span><span class="o">&lt;</span><span class="kt">char</span><span class="o">&gt;</span><span class="w"> </span><span class="n">deviceELF</span><span class="p">(</span><span class="n">binDataSizeRet</span><span class="p">);</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtcGetBinData</span><span class="p">(</span><span class="n">prog</span><span class="p">,</span><span class="w"> </span><span class="n">deviceELF</span><span class="p">.</span><span class="n">data</span><span class="p">()));</span>

<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclInit</span><span class="p">(</span><span class="nb">nullptr</span><span class="p">));</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtSetDevice</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>
<span class="w">    </span><span class="n">aclrtStream</span><span class="w"> </span><span class="n">stream</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtCreateStream</span><span class="p">(</span><span class="o">&amp;</span><span class="n">stream</span><span class="p">));</span>

<span class="w">    </span><span class="n">aclrtBinHandle</span><span class="w"> </span><span class="n">binHandle</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="w">    </span><span class="n">aclrtBinaryLoadOptions</span><span class="w"> </span><span class="n">loadOption</span><span class="p">;</span>
<span class="w">    </span><span class="n">loadOption</span><span class="p">.</span><span class="n">numOpt</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="w">    </span><span class="n">aclrtBinaryLoadOption</span><span class="w"> </span><span class="n">option</span><span class="p">;</span>
<span class="w">    </span><span class="n">option</span><span class="p">.</span><span class="n">type</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ACL_RT_BINARY_LOAD_OPT_MAGIC</span><span class="p">;</span>
<span class="w">    </span><span class="n">option</span><span class="p">.</span><span class="n">value</span><span class="p">.</span><span class="n">magic</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ACL_RT_BINARY_MAGIC_ELF_AICORE</span><span class="p">;</span>
<span class="w">    </span><span class="n">loadOption</span><span class="p">.</span><span class="n">options</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="o">&amp;</span><span class="n">option</span><span class="p">;</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtBinaryLoadFromData</span><span class="p">(</span><span class="n">deviceELF</span><span class="p">.</span><span class="n">data</span><span class="p">(),</span><span class="w"> </span><span class="n">binDataSizeRet</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">loadOption</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">binHandle</span><span class="p">));</span>

<span class="w">    </span><span class="n">aclrtFuncHandle</span><span class="w"> </span><span class="n">funcHandle</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="o">*</span><span class="n">funcName</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="s">&quot;hello_world&quot;</span><span class="p">;</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtBinaryGetFunction</span><span class="p">(</span><span class="n">binHandle</span><span class="p">,</span><span class="w"> </span><span class="n">funcName</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">funcHandle</span><span class="p">));</span>

<span class="w">    </span><span class="c1">// 核函数（Kernel）执行</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">numBlocks</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="w">    </span><span class="kt">void</span><span class="w"> </span><span class="o">*</span><span class="n">kernelArgs</span><span class="p">[]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{};</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtLaunchKernelWithArgsArray</span><span class="p">(</span><span class="n">funcHandle</span><span class="p">,</span><span class="w"> </span><span class="n">numBlocks</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="p">,</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">,</span><span class="w"> </span><span class="n">kernelArgs</span><span class="p">));</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtSynchronizeStream</span><span class="p">(</span><span class="n">stream</span><span class="p">));</span>

<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtBinaryUnLoad</span><span class="p">(</span><span class="n">binHandle</span><span class="p">));</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtDestroyStream</span><span class="p">(</span><span class="n">stream</span><span class="p">));</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtResetDevice</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclFinalize</span><span class="p">());</span>
<span class="w">    </span><span class="c1">// 编译和运行均已结束，销毁程序</span>
<span class="w">    </span><span class="n">ASCENDC_CHECK</span><span class="p">(</span><span class="n">aclrtcDestroyProg</span><span class="p">(</span><span class="o">&amp;</span><span class="n">prog</span><span class="p">));</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div><p>编译命令如下，编译时需要设置-I\${ASCEND_HOME_PATH}/include，用于找到aclrtc相关头文件，并设置-L\${ASCEND_HOME_PATH}/lib64链接acl_rtc动态库。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>g++ rtc_hello_world.cpp -I\${ASCEND_HOME_PATH}/include -L\${ASCEND_HOME_PATH}/lib64 -lascendcl -lacl_rtc -o main
</code></pre></div><p>对于非模板核函数（Kernel）（如<code>hello_world</code>），编译器可自动导出符号，无需额外操作。<br> 当核函数（Kernel）为模板函数时，编译器无法自动确定需要导出的特化实例，需要通过<code>aclrtcAddNameExpr</code>手动注册需要导出的核函数（Kernel）名（含模板参数）；编译后通过<code>aclrtcGetLoweredName</code>获取mangled name，用于后续<code>aclrtBinaryGetFunction</code>查找句柄。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 注册需要导出的核函数（Kernel）名（含模板参数）</span>
<span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">kernelNameExpr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="s">&quot;Kernel::add_custom&lt;float&gt;&quot;</span><span class="p">;</span>
<span class="n">aclrtcAddNameExpr</span><span class="p">(</span><span class="n">prog</span><span class="p">,</span><span class="w"> </span><span class="n">kernelNameExpr</span><span class="p">);</span>
<span class="c1">// ... 编译流程aclrtcCompileProg ...</span>
<span class="c1">// 获取编译后的mangled name</span>
<span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">manglingName</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="s">&quot;&quot;</span><span class="p">;</span>
<span class="n">aclrtcGetLoweredName</span><span class="p">(</span><span class="n">prog</span><span class="p">,</span><span class="w"> </span><span class="n">kernelNameExpr</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">manglingName</span><span class="p">);</span>
</code></pre></div><p>完整样例请参考：<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/02_features/05_aclrtc/rtc_template_add/README.md">rtc_template_add</a>。</p></article></div>`,1)])])}const m=a(l,[["render",t]]);export{w as __pageData,m as default};
